static class CorrelationRoutes
{
    sealed record ToggleRequest(int Version, bool Enabled = true);
    sealed record AssignRequest(int PackVersion, Guid? EndpointId, Guid? EndpointGroupId, bool Enabled = true);
    sealed record SimulationRequest(Guid CorrelationRuleId, int Version, CorrelationObservation[] Observations);
    sealed record EvaluationRequest(CorrelationObservation Observation, bool ProductionFindings = true, DetectionExecutionMode Mode = DetectionExecutionMode.Live);
    sealed record ReplayRequest(Guid CorrelationRuleId, int Version, DateTimeOffset From, DateTimeOffset To, bool ProductionFindings = false, CorrelationObservation[]? ControlledObservations = null);
    sealed record ExportRequest(string Format, CorrelatedFindingQuery Query, int MaximumRecords = 10_000);

    public static void Map(WebApplication app)
    {
        app.MapGet("/api/v1/correlation-packs", Packs).RequirePermission("correlation:read");
        app.MapPost("/api/v1/correlation-packs", CreatePack).RequirePermission("correlation:pack:manage");
        app.MapGet("/api/v1/correlation-packs/{id:guid}", Pack).RequirePermission("correlation:read");
        app.MapGet("/api/v1/correlation-packs/{id:guid}/history", PackHistory).RequirePermission("correlation:read");
        app.MapPost("/api/v1/correlation-packs/{id:guid}:enable", EnablePack).RequirePermission("correlation:activate");
        app.MapPost("/api/v1/correlation-packs/{id:guid}:disable", DisablePack).RequirePermission("correlation:deactivate");
        app.MapPost("/api/v1/correlation-packs/{id:guid}:assign", AssignPack).RequirePermission("correlation:assignment:manage");
        app.MapGet("/api/v1/correlation-rules", Rules).RequirePermission("correlation:read");
        app.MapPost("/api/v1/correlation-rules", CreateRule).RequirePermission("correlation:draft:manage");
        app.MapGet("/api/v1/correlation-rules/{id:guid}", Rule).RequirePermission("correlation:read");
        app.MapGet("/api/v1/correlation-rules/{id:guid}/versions", RuleHistory).RequirePermission("correlation:read");
        app.MapPost("/api/v1/correlation-rules/{id:guid}/versions", VersionRule).RequirePermission("correlation:draft:manage");
        app.MapPost("/api/v1/correlation-rule-versions/{id:guid}/{version:int}:validate", Validate).RequirePermission("correlation:draft:manage");
        app.MapPost("/api/v1/correlation-rule-versions/{id:guid}/{version:int}:test", Test).RequirePermission("correlation:draft:manage");
        app.MapGet("/api/v1/correlation-rule-versions/{id:guid}/{version:int}/tests", Tests).RequirePermission("correlation:read");
        app.MapPost("/api/v1/correlation-rule-versions/{id:guid}/{version:int}:activate", Activate).RequirePermission("correlation:activate");
        app.MapPost("/api/v1/correlation-rules/{id:guid}:disable", Disable).RequirePermission("correlation:deactivate");
        app.MapPost("/api/v1/correlation-rules/{id:guid}:rollback", Rollback).RequirePermission("correlation:activate");
        app.MapPost("/api/v1/correlation-rules/{id:guid}:assign", AssignRule).RequirePermission("correlation:assignment:manage");
        app.MapPost("/api/v1/correlation-simulations", Simulate).RequirePermission("correlation:simulation:run");
        app.MapPost("/internal/v1/correlation-observations:evaluate", Evaluate).RequirePermission("system:admin");
        app.MapPost("/internal/v1/correlation-production-pack:seed", Seed).RequirePermission("system:admin");
        app.MapPost("/api/v1/correlation-replays", Replay).RequirePermission("correlation:replay:run");
        app.MapGet("/api/v1/correlation-replays/{id:guid}", ReplayStatus).RequirePermission("correlation:replay:run");
        app.MapPost("/api/v1/correlation-replays/{id:guid}:cancel", CancelReplay).RequirePermission("correlation:replay:run");
        app.MapGet("/api/v1/correlation-replays/{id:guid}/results", ReplayResults).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlated-findings", Findings).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlated-findings/{id:guid}", Finding).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlated-findings/{id:guid}/evidence", Evidence).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlated-findings/{id:guid}/timeline", Timeline).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlated-findings/{id:guid}/child-findings", Children).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlated-findings/{id:guid}/entity-relationships", Relationships).RequirePermission("correlated-finding:read");
        app.MapGet("/api/v1/correlation-health", Health).RequirePermission("correlation:health:read");
        app.MapGet("/api/v1/mitre-coverage", Coverage).RequirePermission("correlation:read");
        app.MapGet("/api/v1/correlation-exclusions", Exclusions).RequirePermission("correlation:exclusion:manage");
        app.MapPost("/api/v1/correlation-exclusions", CreateExclusion).RequirePermission("correlation:exclusion:manage");
        app.MapPost("/api/v1/correlated-finding-exports", Export).RequirePermission("correlated-finding:export");
        app.MapGet("/api/v1/correlated-finding-exports/{id:guid}/manifest", ExportManifest).RequirePermission("correlated-finding:export");
        app.MapGet("/api/v1/correlated-finding-exports/{id:guid}/content", ExportContent).RequirePermission("correlated-finding:export");
        app.MapPost("/api/v1/correlated-finding-exports/{id:guid}/download-url", ExportUrl).RequirePermission("correlated-finding:export");
        app.MapGet("/api/v1/correlated-finding-exports/{id:guid}/download", ExportDownload);
